from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class AccountServiceUserPropertys(SchemaObject):
    user_type = SchemaField(name='UserType', not_null=True)
    is_old_pwd_needed = SchemaField(name='IsOldPwdNeeded', not_null=True)
    username = SchemaField(name='username', optional=True)

    def __init__(self, user_type, is_old_pwd_needed, username=None):
        self.user_type = user_type
        self.is_old_pwd_needed = is_old_pwd_needed
        self.username = username

        super(AccountServiceUserPropertys, self).__init__()
